ALTER TABLE messages ADD COLUMN IF NOT EXISTS is_deleted_by_participant BOOLEAN DEFAULT FALSE; ALTER TABLE chats ADD COLUMN IF NOT EXISTS is_deleted_by_participant BOOLEAN DEFAULT FALSE; DROP POLICY IF EXISTS "Employee can update messages" ON messages; CREATE POLICY "Employee can update messages" ON messages AS PERMISSIVE FOR UPDATE TO authenticated USING (auth.uid() IN (SELECT auth_id FROM public.employees)); DROP POLICY IF EXISTS "Employee can update their chats" ON chats; CREATE POLICY "Employee can update their chats" ON chats AS PERMISSIVE FOR UPDATE TO authenticated USING (auth.uid() IN (SELECT auth_id FROM public.employees));
